    const comp=(list,lbl)=>{let prev=null;return per(list,lbl).map(({p,lbl})=>{const r=res(d,p.a,p.b);const o={per:lbl,rec:r.receita,desp:r.gastos,luc:r.lucro,mg:r.receita?r.lucro/r.receita:NaN,var:prev!=null&&prev!==0?(r.lucro-prev)/Math.abs(prev):NaN};prev=r.lucro;return o;});};
