  fecharCaixa(){const s=this.state,d=s.data;if(d.fechamentos.some(f=>f.data===TODAY))return this.toast('O caixa de hoje já foi fechado.');const id=cxId(d);const si=saldo(d,id,addD(TODAY,-1)),sf=saldo(d,id,TODAY);const L=act(d).filter(l=>l.data===TODAY);const e=L.reduce((a,l)=>a+((l.tipo==='entrada'&&l.conta===id)||(l.tipo==='transf'&&l.destino===id)?l.valor:0),0);
    this.ask('Fechar o caixa de hoje?','Saldo final em dinheiro: '+brl(sf)+'. O fechamento fica registrado com seu usuário.',()=>{this.mut(dd=>{dd.fechamentos.unshift({data:TODAY,saldoInicial:si,entradas:e,saidas:r2(si+e-sf),saldoFinal:sf,usuario:s.user,quando:nowISO()});},'Fechou o caixa','Caixa',dbr(TODAY)+' · '+brl(sf));this.toast('Caixa fechado.');},'Fechar caixa');}

